use vstd::prelude::*;
use vstd::slice::slice_to_seq;
use vstd::vec::{Vec, to_seq};

verus! {

    // concat: &[i32] × &[i32] → Vec<i32>
    // ensures
    //   1) the length of the result is a.len() + b.len(), and
    //   2) the sequence representing the result is exactly
    //      slice_to_seq(a) + slice_to_seq(b).
    fn concat(a: &[i32], b: &[i32]) -> (res: Vec<i32>)
        ensures res.len() == a.len() + b.len(),
        ensures to_seq(&res) == slice_to_seq(a) + slice_to_seq(b),
    {
        // We start with an empty Vec<i32>
        let mut res: Vec<i32> = Vec::new();

        // First loop: copy all of `a` in order.
        let mut i: usize = 0;
        while i < a.len()
            invariant i <= a.len(),
            // res.len() = i  and  res@ = a@[0..i]
            invariant res.len() == i,
            invariant to_seq(&res) == slice_to_seq(a)[0..i],
            decreases a.len() - i,
        {
            res.push(a[i]);
            i += 1;
        }

        // Second loop: copy all of `b` in order, immediately after `a`.
        let mut j: usize = 0;
        while j < b.len()
            invariant j <= b.len(),
            // now res.len() = a.len() + j
            invariant res.len() == a.len() + j,
            // and res@ = a@ + b@[0..j]
            invariant to_seq(&res) == slice_to_seq(a) + slice_to_seq(b)[0..j],
            decreases b.len() - j,
        {
            res.push(b[j]);
            j += 1;
        }

        // At this point j == b.len(), so
        //   res.len() == a.len() + b.len(),
        //   to_seq(&res) == slice_to_seq(a) + slice_to_seq(b)[0..b.len()]
        // but b@[0..b.len()] is exactly b@, so we get the final postcondition.

        res
    }
}

fn main() {
    // You can add some quick runtime checks here if you like:
    let a = &[1,2,3];
    let b = &[4,5];
    let c = concat(a, b);
    assert!(c.len() == 5);
    assert!(c[0] == 1 && c[4] == 5);
}